PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?pct / 100) AS ?petroleo) WHERE {
  {
    SELECT ?c (SUM(?oil) AS ?oilC) WHERE {
      ?p a energia:WellProduction ;
         energia:inConcession ?c ;
         energia:oil ?oil .
    }
    GROUP BY ?c
  }
  {
    SELECT ?c (SUM(?percent) AS ?pct) WHERE {
      ?s a energia:Stake ;
         energia:inConcession ?c ;
         energia:partner ?co ;
         energia:percent ?percent .
      ?co energia:name ?n .
      FILTER(REGEX(UCASE(STR(?n)), "^YPF( |$|\\.)"))
    }
    GROUP BY ?c
  }
}

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?pozo) AS ?n) WHERE {
  ?pozo a energia:Well ;
        energia:operator ?empresa .
  ?empresa energia:name ?nombre .
  FILTER(REGEX(STR(?nombre), "^YPF", "i"))
}

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?name WHERE {
  ?v a energia:DetectedVenting ;
     energia:inConcession ?c .
  ?c energia:name ?name .
}
GROUP BY ?c ?name
ORDER BY DESC(COUNT(?v))
LIMIT 5

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?name WHERE {
  {
    SELECT ?c (SUM(?oil) AS ?total) WHERE {
      ?p a energia:UnconventionalProduction ;
         energia:declaredBy ?c ;
         energia:oil ?oil .
    }
    GROUP BY ?c
    ORDER BY DESC(?total)
    LIMIT 5
  }
  ?c energia:name ?name .
}
ORDER BY DESC(?total)

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a energia:VentingFarFromPipeline .
}

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?v) AS ?n) WHERE {
  ?v a energia:DetectedVenting ;
     energia:inConcession ?c ;
     energia:date ?d .
  FILTER(SUBSTR(STR(?d), 1, 10) >= "2024-01-01")
  ?s a energia:SurroundingsLink ;
     energia:aboutVenting ?v ;
     energia:protectedArea ?pa .
  FILTER(STRLEN(STR(?pa)) > 0)
}

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT DISTINCT ?name WHERE {
  ?p a energia:WellProduction ;
     energia:declaredBy ?c .
  ?c energia:lei ?lei ;
     energia:name ?name .
}

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a energia:OperatorChange ;
     energia:inConcession ?conc ;
     energia:previousCompany ?prev ;
     energia:newCompany ?new ;
     energia:month ?m .
  OPTIONAL { ?prev energia:name ?pn }
  OPTIONAL { ?new energia:name ?nn }
  BIND(UCASE(COALESCE(STR(?pn), "")) AS ?p)
  BIND(UCASE(COALESCE(STR(?nn), "")) AS ?q)
  FILTER(?prev != ?new)
  FILTER(!(CONTAINS(?p, "GEOPARK") && CONTAINS(?q, "GEOPARK")))
  FILTER(!(CONTAINS(?p, "PLUSPETROL") && CONTAINS(?q, "PLUSPETROL")))
  FILTER(!((CONTAINS(?p, "CGC") || CONTAINS(?p, "GENERAL DE COMBUSTIBLES")) && (CONTAINS(?q, "CGC") || CONTAINS(?q, "GENERAL DE COMBUSTIBLES"))))
}

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?name WHERE {
  {
    SELECT ?c (SUM(?g) AS ?total) WHERE {
      ?p a energia:ShaleProduction ;
         energia:declaredBy ?c ;
         energia:gas ?g .
    }
    GROUP BY ?c
    ORDER BY DESC(?total)
    LIMIT 5
  }
  ?c energia:name ?name .
}
ORDER BY DESC(?total)
